    rdfs:label "Assessment Participant"@en .

#################################################################
#    Axis 1: Purpose Category Reification & Bridge Definitions
#################################################################

ea:hasAssessmentPurpose
    a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:AssessmentPurpose ;
    owl:inverseOf ea:isAssessmentPurposeOf ;
    rdfs:label "has assessment purpose"@en .

ea:isAssessmentPurposeOf
    a owl:ObjectProperty ;
    rdfs:domain ea:AssessmentPurpose ;
    rdfs:range ea:Assessment ;
    rdfs:label "is assessment purpose of"@en .

ea:DiagnosticPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Diagnostic Purpose"@en .

ea:FormativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Formative Purpose"@en ;
    skos:altLabel "Assessment For Learning Purpose"@en, "Educative Purpose"@en .

ea:SummativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Summative Purpose"@en ;
    skos:altLabel "Assessment Of Learning Purpose"@en, "Evaluative Purpose"@en .

ea:PlacementPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Placement Purpose"@en ;
    skos:altLabel "Initial Assessment Purpose"@en, "Pre-Assessment Purpose"@en .

ea:InterimPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Interim Purpose"@en ;
    skos:altLabel "Benchmark Purpose"@en .

ea:ScreeningPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Screening Purpose"@en .

ea:AssessmentPurpose owl:disjointUnionOf (
    ea:DiagnosticPurpose
    ea:FormativePurpose
    ea:SummativePurpose
    ea:PlacementPurpose
    ea:InterimPurpose
    ea:ScreeningPurpose
) .

ea:DiagnosticAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAssessmentPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ]
        )
    ] ;
    rdfs:label "Diagnostic Assessment"@en ;
    rdfs:comment "Tension in corpus: In Passage 2 and 3, diagnostic assessment is classified as a coordinate category alongside placement, formative, and summative assessments. In other passages (Passage 3, 24, 29), diagnostic assessment is subordinated as a common form or component of formative assessment."@en .

ea:FormativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAssessmentPurpose ; owl:someValuesFrom ea:FormativePurpose ]
        )
    ] ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Assessment For Learning"@en, "Classroom Assessment"@en, "Educative Assessment"@en ;
    rdfs:comment "Tension in corpus: Some passages state formative assessment is not graded and low-stakes, whereas other passages state that formative results may count or be formally recorded."@en .

ea:SummativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAssessmentPurpose ; owl:someValuesFrom ea:SummativePurpose ]
        )
    ] ;
    rdfs:label "Summative Assessment"@en ;
    skos:altLabel "Assessment Of Learning"@en, "Summative Evaluation"@en .

ea:PlacementAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAssessmentPurpose ; owl:someValuesFrom ea:PlacementPurpose ]
        )
    ] ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en, "Placement Evaluation"@en, "Pre-Assessment"@en, "Threshold Knowledge Test"@en .

ea:InterimAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAssessmentPurpose ; owl:someValuesFrom ea:InterimPurpose ]
        )
    ] ;
    rdfs:label "Interim Assessment"@en ;
    skos:altLabel "Benchmark Assessment"@en ;
    rdfs:comment "Tension in corpus: Interim assessments are evaluated periodically to monitor progress towards summative tests; some educators classify them as formative while others classify them as summative."@en .

ea:ScreeningAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasAssessmentPurpose ; owl:someValuesFrom ea:ScreeningPurpose ]
        )
    ] ;
    rdfs:label "Screening Assessment"@en .

# Subordination claim from corpus modeled alongside coordinate status:
ea:DiagnosticAssessment rdfs:subClassOf ea:FormativeAssessment .

